PRIOR = ('open as far as checked (2 Nov 2026: known.py on the shelfmark and correspondents, no hit; '
         'Tomokiyo, Lasry, the edition and the literature not searched)')


def link(repo, term, rid, c, label='Archives Portal Europe record'):
    return [{'label': label, 'href': BASE % (repo, term, rid, c)}]


def row(year, date, title, corr, place, lang, region, period, shelf, folio, cls, status, why, imp, sol, dif, links,
        scan='unknown', access='scans not checked; record is on Archives Portal Europe, the holding archive may publish images', **kw):
    r = dict(year=year, date=date, title=title, correspondents=corr, place=place, language=lang, region=region,
             period=period, shelfmark=shelf, folio_note=folio, cls=cls, status=status, why=why, importance=imp,
             solvability=sol, difficulty=dif,
             score_note='Scored from the archive description during the Nov 2026 Archives Portal Europe sweep (research/sweep_2026-11_ape/); not viewed',
             verify=kw.pop('verify', 'Open the record at the holding archive; view the scans; measure the cipher; look for a key or decipherment in the same fonds.'),
             links=links, seen='catalogue', source='Archives Portal Europe sweep', prior_art=PRIOR,
             needs_archive_scan=scan, access_note=access)
    r.update(kw)
    return r


