def main():
    out = os.path.join(HERE, 'candidates.json')
    with open(out, 'w', encoding='utf-8') as fh:
        json.dump(R, fh, ensure_ascii=False, indent=1)
    print(len(R), 'rows ->', out)


if __name__ == '__main__':
    main()
